/**
 * Рендерер звіту інспектора: payload -> HTML. ЧИСТИЙ модуль — ні DOM, ні CSSOM,
 * ні звернення до документа: рахує звіт `inspector-dom.js` УСЕРЕДИНІ iframe
 * макета, і він лишається єдиним, хто бачить живий DOM. Тут тільки малювання.
 *
 * Лежить у `vendor/`, хоча малює батьківську панель, бо його імпортують ОБИДВА
 * документи: права панель оболонки і — для сторінки, відкритої без канваса, —
 * сам оверлей. Асети віддаються як `{origin}/app/vendor` (`serve.py`), тож
 * `../i18n.js` з iframe резолвиться в той самий `/app/i18n.js`.
 *
 * Вигляд — із затвердженого прототипу `docs/proto/shell.html` (`inspPanel`);
 * імена класів — за конвенцією репозиторію (`insp-*`), не прототипу.
 */
import { esc } from "../esc.js";
import { t } from "../i18n.js";
/* Нормалізація значення — з ЯДРА, тим самим міряльним інструментом, що й
   решта інспектора: пікеру потрібен `#rrggbb`, а браузер віддає
   `rgb(26, 28, 31)`. Друга, «своя» конвертація тут розійшлася б із тією, якою
   `setEdit` звіряє повернення до початкового, — і скидання ручки перестало б
   спрацьовувати рівно на кольорах. Ядро чисте (ні DOM, ні CSSOM), тож
   охоронець чистоти цього модуля лишається чинним. */
import { isSpaceProfile, normalizeValue } from "./inspector-core.js";

/** Заголовки секцій. Ключі — з `GROUPS` (`inspector-dom.js`). `flex`
 *  приходить і для grid-контейнера, тож назва нейтральна — щоб не брехати. */
const TITLE_KEY = { box: "inspSecBox", layout: "inspSecLayout",
  flex: "inspSecFlex", type: "inspSecType", color: "inspSecColor" };

/** Секція без заголовка краща за впалий звіт: `t()` кидає на невідомому
 *  ключі, тож старий ідіом `TITLE_KEY[k] || k` (з `inspector.js`, де
 *  `_titles` був таблицею РЯДКІВ) означав би тут не запасний варіант, а
 *  виняток на весь звіт від нової групи в `GROUPS` (`inspector-dom.js`). */
const title = (k) => (TITLE_KEY[k] ? t(TITLE_KEY[k]) : k);

/**
 * Підказки «хардкод → …» — у ТИТУЛ поля, а не бейджем у рядку (T-39).
 *
 * Кожна підказка несе РІВЕНЬ упевненості (`tier`, див. `hintFor` в
 * `inspector-core.js`): 'used' — токен уже вживають у макеті для цієї ж родини
 * властивостей, будь-що інше — здогад (там збіг лише за значенням і його
 * формою). Здогад позначається СЛОВОМ (`inspHintGuess`), бо в титулі немає
 * ні кольору, ні прозорості: здогад, поданий як факт, — це та сама брехня про
 * токен, від якої інспектор і лікувався. До T-39 різницю ніс клас
 * `insp-maybe` (тьмяніший бейдж) — він зник разом із бейджем, а різниця
 * лишилась, лише іншим носієм.
 *
 * ⚠️ ДОВЕДЕНИМ вважається РІВНО `tier === 'used'`, а не «все, що не 'shape'».
 * Різниця не теоретична: `hintOf` (`app/tuner-model.js`) на невідомому рівні
 * ставить у пакет здогад, і дзеркальне правило «не 'shape' = факт» тут
 * означало б, що ОДНА підказка їде Клоду як здогад, а дизайнеру показується
 * як факт. Два описи одного рівня мусять розходитись у бік обережності, а не
 * в бік упевненості.
 *
 * ⚠️ Підказка без імені ВИКИДАЄТЬСЯ — тим самим правилом, що в `hintOf`.
 *
 * Без `esc()` свідомо: результат їде в титул, який екранується ОДИН раз у
 * місці вставки (`fieldTitle` → `title="${esc(…)}"`). Друге екранування дало б
 * `&amp;lt;` на екрані — рівно та вада, від якої береже тест «амперсанд
 * екранується першим» (`tests/esc.test.mjs`).
 */
function hintText(list) {
  if (!Array.isArray(list) || !list.length) return "";
  const parts = [];
  for (const h of list) {
    const name = h && typeof h.name === "string" ? h.name : "";
    if (!name) continue;
    parts.push(h.tier === "used" ? name : t("inspHintGuess", name));
  }
  return parts.length ? ` → ${parts.join(", ")}` : "";
}

/**
 * Вирок СЛОВАМИ — для титула поля.
 *
 * ⛔ ЖОДНОГО імені токена для 'unlinked' і 'unknown':
 *   'unlinked' — джерело не звелося з тим, що показує браузер;
 *   'unknown'  — наша модель каскаду розійшлася з браузером.
 * Показати там токен = збрехати дизайнеру про походження значення. Барʼєр
 * структурний (гілка не має доступу до `d.token` взагалі), а не «не забути
 * прибрати»: саме так він і пережив переїзд бейджа в титул.
 */
function verdictText(d) {
  if (d.verdict === "token") return d.token ? String(d.token) : "";
  if (d.verdict === "hardcode") return t("inspHardcode") + hintText(d.hint);
  /* 'off-ds' — токен є, але ДС його не знає. Імʼя показуємо: походження тут
     доведене рівно так само, як у 'token' (var() розкрилась у те, що показує
     браузер), просто джерело виявилось не дизайн-системою. Заборона на імʼя
     стосується лише 'unlinked'/'unknown', де не доведено САМЕ походження. */
  if (d.verdict === "off-ds") {
    return t("inspOffDs", d.token ? String(d.token) : "") + hintText(d.hint);
  }
  /* 'overridden' — і ЧИМ воно має бути. Сказати «перевизначено» й не сказати
     приписаного означало б лишити дизайнера з тим самим питанням, з якого
     T-40 і почався. Значень буває кілька (@media у ДС) — перелічуємо всі, бо
     кожне з них законне. */
  if (d.verdict === "overridden") {
    const want = Array.isArray(d.ds) ? d.ds.filter(Boolean).join(", ") : "";
    return t("inspOverridden", d.token ? String(d.token) : "", want);
  }
  if (d.verdict === "unknown") return t("inspUnknown");
  return "";
}

/**
 * Вирок КРАПКОЮ (варіант А затвердженого макета `docs/proto/tuner-panel.html`):
 * зелена — значення прийшло з токена, бурштинова — хардкод, сіра — правило не
 * розібрали. Імʼя токена й підказки — у титулі (`verdictText`).
 *
 * 'unlinked' крапки НЕ отримує, і це не пропуск: так було й до T-39 (бейдж
 * там теж не малювався), і так намальовано в макеті — нуль відступу
 * `unlinked` у кожному другому рядку, і крапка на кожному з них перетворила б
 * вирок із сигналу на тло.
 *
 * Класи виписані ПОВНИМИ літералами в кожній гілці, а не зібрані з шматків:
 * охоронець css-guards витягує список класів регекспом по атрибуту `class`, і
 * інтерполяція в ньому лишила б йому `${…}` замість імені класу.
 */
function dotHTML(d) {
  if (d.verdict === "token") return `<span class="insp-dot insp-dot--tok"></span>`;
  if (d.verdict === "hardcode") return `<span class="insp-dot insp-dot--hard"></span>`;
  /* Два нових стани — і вага в них РІЗНА, бо різна й частота вади. Виміряно
     на справжніх макетах 22.09.2026: 'off-ds' на лендінгу — норма (198 із 589
     змінних `bf360` законно поза ДС), а 'overridden' не буває нормою ніколи —
     це ім'я з ДС, яке поводиться інакше, ніж обіцяє. Тому 'overridden' бере
     той самий червоний, що й «перекриття» в лінійці (єдиний інший вирок про
     ваду), а 'off-ds' — тихе кільце: видно, що це не зелена крапка, і не
     кричить на кожному другому рядку. Крапка, що кричить завжди, перестає
     бути сигналом — рівно те, що сталося з зеленою до T-40. */
  if (d.verdict === "off-ds") return `<span class="insp-dot insp-dot--offds"></span>`;
  if (d.verdict === "overridden") return `<span class="insp-dot insp-dot--over"></span>`;
  if (d.verdict === "unknown") return `<span class="insp-dot insp-dot--unk"></span>`;
  return "";
}

/**
 * ДОРОГА НАЗАД У ДИЗАЙН-СИСТЕМУ — і вона ж крапка вироку.
 *
 * ⛔ ЧОМУ КНОПКА ОБГОРТАЄ КРАПКУ, а не стає поруч. Панель — 308px, і T-39
 * щойно вигнав звідти перенос рядка: висота поля СТАЛА, нічого не
 * переноситься. Окремий контрол у полі — це ще 14px ширини в смузі, де на
 * чотири відступи вже й так лишається по 45px на поле. Обгорнувши крапку, ми
 * не додаємо в поле жодного елемента: те саме місце, той самий вирок, просто
 * тепер на нього можна натиснути. Відʼємні поля (`.insp-snap`, styles.css)
 * зʼїдають різницю в 7px, тож геометрія рядка не рухається взагалі.
 *
 * Читається це теж просто: крапка каже, ЩО не так, і натискання це лагодить.
 *
 * ⚠️ Кнопка малюється ЛИШЕ там, де ручки живі (`tunable`): проводка
 * (`data-act="inspsnap"` → `BAR_ACTIONS`) живе в батьківському вікні, а в
 * shadow-корені оверлея її немає й не буде — та сама межа й та сама причина,
 * що в `NUMERIC`/`reportHTML`. Підроблена кнопка гірша за чесну крапку.
 *
 * ⛔ БЕЗ `title` на самій кнопці: титул на кнопці накрив би титул поля рівно
 * там, де дизайнер водить мишею, і походження значення (заради якого титул і
 * заводили в T-39) стало б невидимим. Про кнопку каже той самий, ОДИН титул
 * поля (`fieldTitle` → `snapKnob`), а читачеві з екрана — `aria-label`.
 */
function snapHTML(d, tunable) {
  const dot = dotHTML(d);
  const snap = tunable && d.snap && typeof d.snap.token === "string" && d.snap.token
    && d.snap.value != null ? d.snap : null;
  if (!snap || !dot) return dot;
  return `<button class="insp-snap" data-act="inspsnap"`
    + ` data-prop="${esc(d.prop)}" data-token="${esc(snap.token)}"`
    + ` data-val="${esc(String(snap.value))}"`
    + ` aria-label="${esc(t("inspSnapTo", snap.token))}">${dot}</button>`;
}

/** Підпис дороги назад — у титул ПОЛЯ (див. `snapHTML`, чому не на кнопку). */
function snapKnob(d, tunable) {
  const snap = tunable && d.snap && typeof d.snap.token === "string" && d.snap.token
    ? d.snap : null;
  return snap ? t("inspSnapKnob", snap.token, String(snap.value)) : "";
}

const COLOR_PROP = /color$/;
/** Значення кольору йде в АТРИБУТ `style`, тож барʼєр тут — цей регексп, а не
 *  `esc()`: `esc()` не чіпає ні `\`, ні дужок. Набір символів свідомо ВУЖЧИЙ
 *  за старий `/^[#\w().,%\s\/-]+$/` (він жив в `inspector.js` до 17.09.2026 і
 *  поїхав звідти разом із розміткою; номера рядка тут свідомо немає — саме
 *  такий номер і зогнив, показуючи на `const DIRS`): без `\` не зібрати
 *  CSS-екранування, без `;`/`:` — другої декларації чи абсолютного URL.
 *  Ціна виміряна: `oklch(… / .5)` і `rgb(0 0 0 / 50%)` лишаються БЕЗ зразка.
 *  Спокуса додати `/` заради них — пастка: разом зі слешем стає досяжним
 *  `url(//чужий-хост/x.png)`, тобто справжній вихід за origin. */
const CSS_SAFE = /^[a-z0-9 ,.()#%-]+$/i;

/* ── Ручки тюнера в полях звіту (Task 14, перебудовані в T-39) ──────────────
   ⛔ Ручка ЖИВА, але нікуди не пише: `applyTune` кладе інлайн-стиль на макет
   (`inspector.js`), а вихід тюнера — пакет РЕКОМЕНДАЦІЙ Клоду. Тут — сама
   лише розмітка ручок; проводку (`data-act` → дія) робить `app.js` тією ж
   делегацією, що й крихти з вкладками.

   Значення В ПОЛІ — це завжди `computed`, тобто те, що показує БРАУЗЕР, а не
   `to` з моделі тюнера. Різниця несуща: поле мусить показувати правду про
   макет, а не намір. Розійтись вони можуть (макет перезавантажили, а
   накручене ще не наклали заново), і тоді чесніше показати браузерне. */

/**
 * Числове значення, яке Є ЧИМ крутити: число з одиницею або без неї.
 * `normal`, `auto`, `block`, `Georgia, serif`, `1px solid #000` сюди не
 * підпадають свідомо. Підробити крутилку там, де кроку не існує, гірше за
 * чесний текст: дизайнер натисне стрілку, нічого не станеться, і далі він не
 * вірить жодній ручці в панелі.
 */
const NUMERIC = /^(-?(?:\d+(?:\.\d+)?|\.\d+))(px|rem|em|%|vh|vw|pt)?$/;

/** Колір, який уміє показати нативний пікер: він знає ЛИШЕ `#rrggbb`.
 *  `rgba(…)` з альфою і `transparent` не знає, тож там лишається текст і
 *  старий зразок — пікер, що мовчки згубив би прозорість, збрехав би про
 *  значення. */
const HEX6 = /^#[0-9a-f]{6}$/;

/**
 * Крок крутилки. Не «1 на все»: крок мусить бути того ж порядку, що й шкала
 * властивості, інакше ручка або нічого не робить, або перестрибує все.
 *   · `font-weight` — 100: шкала ваг саме така, крок 1 там не означає нічого;
 *   · без одиниці й `em`/`rem` — 0.1: це `line-height: 1.5` і `1.25rem`, де
 *     цілий крок — це вдвічі-втричі;
 *   · решта (px, %, vh…) — 1.
 * ГРУБИЙ крок (Shift) — удесятеро більший, і рахує його `app.js` із цього ж
 * числа: множник, записаний у двох місцях, колись розійшовся б.
 */
function stepFor(prop, unit) {
  if (prop === "font-weight") return 100;
  if (!unit || unit === "em" || unit === "rem") return 0.1;
  return 1;
}

/** Стрілка боку — замість повного імені властивості (прийом Figma, варіант А
 *  макета): чотири відступи стають однією смугою, а не чотирма рядками.
 *  Гліфи літеральні, як `px` і `<kbd>Esc</kbd>`: це не текст, що потребує
 *  перекладу, а позначення сторони, однакове в обох мовах. Повне імʼя
 *  властивості лишається в титулі поля — і в `aria-label`, бо для читача з
 *  екрана стрілка не каже нічого. */
const SIDE_ICON = {
  "margin-top": "↑", "margin-right": "→", "margin-bottom": "↓", "margin-left": "←",
  "padding-top": "↑", "padding-right": "→", "padding-bottom": "↓", "padding-left": "←",
};

/* ⚠️ ІКОНОК широкого рядка (`▤` для `display`, `A` для `font-family`) тут
   немає, хоч макет їх малює, — і це свідома відмова, а не забуте. У макеті
   іконка стояла ЗАМІСТЬ імені властивості («▤ display · block»); для кольорів
   так не виходить: `color`, `background-color` і `border-color` — три
   однакові плитки поспіль, і без імені їх не розрізнити взагалі. Отже імʼя у
   широкому рядку потрібне завжди (`insp-nm`), а разом з іменем іконка вже
   нічого не додає — лише зʼїдає ширину, якої бракує усіченому значенню
   (`font-family` у панелі 308px). */

/**
 * Титул поля — усе, чого в самому полі більше не видно.
 *
 * Порядок частин: властивість · повне значення (коли в полі воно усічене) ·
 * «було …» (коли накручено) · вирок і підказки. Саме в цьому порядку його й
 * читають: спершу «що це», потім «що тут насправді», і аж потім «звідки воно».
 *
 * ⛔ Старого значення в РЯДКУ більше немає (T-39): воно є в списку змін
 * унизу панелі («було → стало»), тобто рядок його дублював — і дублював
 * дорого: перекреслене «було», поле, одиниця й бейдж не влазили в колонку
 * 185px, рядок переносився і виростав із 16px до 44px. Тут лишився слід, за
 * яким видно, від чого пішли, без жодного пікселя висоти.
 */
function fieldTitle(d, tuned, full, knob, snap) {
  const parts = [String(d.prop)];
  if (full) parts.push(full);
  if (tuned) parts.push(t("inspTuneWas", tuned.from));
  /* Правка є в пакеті, а на цьому документі її немає — і це мусить бути
     сказано СЛОВАМИ, а не лише блідим тлом: число в полі при цьому
     недоторкане (сторінчине), а бейдж «накручено» поруч стверджує протилежне. */
  if (tuned && tuned.missing) parts.push(t("inspTunerNotApplied"));
  const v = verdictText(d);
  if (v) parts.push(v);
  /* Підказка про саму ручку — В ЦЕЙ ЖЕ титул, а не на контрол. Титул на
     полі й титул на полі вводу всередині нього — це ДВА різні спливні
     написи, і виграє внутрішній: він накриває майже всю площу поля. Тобто
     походження значення (те, заради чого титул і заводили в T-39) дизайнер
     побачив би лише навівшись на тонку смужку падингу. Один титул на поле —
     і в ньому все, що про це поле відомо. */
  if (knob) parts.push(knob);
  if (snap) parts.push(snap);
  return parts.join(" · ");
}

/**
 * Одне ПОЛЕ звіту: іконка, значення (крутилкою, пікером або усіченим текстом),
 * одиниця всередині поля і крапка вироку.
 *
 * Несуче правило T-39: ВИСОТА ПОЛЯ СТАЛА. Нічого не переноситься — довге
 * значення усікається (`insp-txt`), одиниця стоїть УСЕРЕДИНІ поля (тож ширина
 * поля не залежить від довжини значення), вирок звузився до крапки. До T-39
 * накручений рядок розганявся з 16px до 44px, і все нижче зʼїжджало на 28px
 * за кожну правку — це і є «скаче», на яке скаржився дизайнер.
 *
 * `tunable` — чи є в ЦЬОМУ документі кому проводити ручку (див. `reportHTML`).
 * Немає — віддаємо текст, тим самим шляхом, яким його вже отримують нечислові
 * значення. Це та сама вимога, що й у `NUMERIC`, лише з іншого боку: там ручку
 * не підробляють там, де кроку не існує, а тут — там, де натиснути її нікуди.
 *
 * `data-prop` на самому полі — адреса рядка звіту для всіх, хто дивиться на
 * панель ззовні (жива перевірка, майбутня проводка): імені властивості в
 * розмітці більше немає ні окремим підписом, ні в смузі відступів, і шукати
 * поле по титулу означало б адресувати його ТЕКСТОМ, який залежить від мови.
 *
 * ⚠️ СТАН — АТРИБУТАМИ (`data-wide`/`data-ro`/`data-tuned`), а не додатковими
 * класами, і це не смак. Охоронець css-guards витягує імена класів регекспом
 * по атрибуту class У САМОМУ СИРЦІ, тож інтерполяція всередині нього лишила б
 * йому шматок шаблону замість імені (про це попереджають коментарі в
 * `dotHTML`). Три незалежні модифікатори дали б вісім повних
 * літералів класу на одне поле; атрибут стану лишає `class="insp-f"` і
 * переносить розгалуження в CSS (`.insp-f[data-tuned]`), де воно й читається
 * як стан. Той самий прийом уже живе в оболонці — `.seg button[aria-pressed=true]`.
 */
function fieldHTML(d, { tunable, tuned, wide }) {
  const value = String(d.computed ?? "");
  const hex = COLOR_PROP.test(d.prop) ? normalizeValue(value) : "";
  const pick = tunable && HEX6.test(hex) ? hex : "";
  const num = tunable ? NUMERIC.exec(value) : null;
  const side = SIDE_ICON[d.prop] || "";

  let body = "";
  let full = "";
  let knob = "";
  if (pick) {
    /* Пікер ПІДМІНЯЄ собою зразок (`insp-sw`), а не стає поруч: дві кольорові
       плитки в одному полі читались би як два різні кольори. */
    body = `<input type="color" class="insp-pick" data-act="insptunecolor"`
      + ` data-prop="${esc(d.prop)}" value="${esc(pick)}"`
      + ` aria-label="${esc(d.prop)}">`
      + `<span class="insp-txt">${esc(value)}</span>`;
    full = value;
    knob = t("inspTuneColor");
  } else if (num) {
    const unit = num[2] || "";
    /* Одиниця — ВСЕРЕДИНІ поля, праворуч від числа (прийом Figma): інакше
       ширина поля танцює за довжиною значення. У смузі відступів її немає
       свідомо — `getComputedStyle` віддає margin/padding ЗАВЖДИ в px, тобто
       там це стала, а не втрачена правда (повна стоїть у титулі), і чотири
       поля в рядок інакше не лишають місця числу. */
    body = `<input type="number" class="insp-num" data-act="insptune"`
      + ` data-prop="${esc(d.prop)}" data-unit="${esc(unit)}"`
      + ` step="${stepFor(d.prop, unit)}" value="${esc(num[1])}"`
      + ` aria-label="${esc(d.prop)}">`
      + (unit && !side ? `<span class="insp-unit">${esc(unit)}</span>` : "");
    full = value;
    knob = t("inspTuneValue");
  } else {
    const sw = COLOR_PROP.test(d.prop) && CSS_SAFE.test(value)
      ? `<span class="insp-sw" style="background:${esc(value)}"></span>` : "";
    body = sw + `<span class="insp-txt">${esc(value) || "—"}</span>`;
    full = value;
  }

  const ro = !pick && !num;
  /* Імʼя властивості — лише в ШИРОКОМУ рядку: у смузі відступів його каже
     стрілка, у парі — підпис над колонкою, а тут сказати нема кому. Воно
     стоїть ПЕРЕД значенням і не усікається саме: усікається значення
     (`insp-txt`), бо імена властивостей короткі й однакової довжини, а
     значення буває на три рядки. */
  return `<div class="insp-f" data-prop="${esc(d.prop)}"`
    + `${wide ? ` data-wide=""` : ""}${ro ? ` data-ro=""` : ""}`
    + `${tuned ? ` data-tuned=""` : ""}${tuned && tuned.missing ? ` data-miss=""` : ""}`
    + ` title="${esc(fieldTitle(d, tuned, full, knob, snapKnob(d, tunable)))}">`
    + (side ? `<span class="insp-ico">${side}</span>` : "")
    + (wide ? `<span class="insp-nm">${esc(d.prop)}</span>` : "")
    + body + snapHTML(d, tunable) + `</div>`;
}

/**
 * Розкладка секцій — що з чим стоїть в одному рядку.
 *
 * Джерело — затверджений макет (`docs/proto/tuner-panel.html`, варіант А):
 * чотири відступи однією смугою зі стрілками, парні властивості у дві
 * колонки. Секція «Відступи» стиснулась із восьми рядків до двох смуг.
 *
 * Порядок блоків тут — порядок на екрані, і він НЕ дорівнює порядку в
 * `GROUPS` (`inspector-dom.js`): у макеті пара «Ширина|Висота» стоїть перед
 * `display`, а `font-family` — перед кеглем. Друге джерело порядку тут
 * законне: `GROUPS` каже, ЩО рахувати, а це — як показувати.
 *
 * ⚠️ Властивість, якої тут немає (уся група `flex`, будь-яка майбутня в
 * `GROUPS`), малюється широким рядком у своєму порядку — не зникає. Це
 * перевіряє окремий тест «жодна властивість payload не загубилась»: таблиця
 * розкладки з одруком інакше тихо зʼїла б рядок звіту.
 */
const LAYOUT = {
  box: [
    { lbl: "inspLblOuter",
      quad: ["margin-top", "margin-right", "margin-bottom", "margin-left"] },
    { lbl: "inspLblInner",
      quad: ["padding-top", "padding-right", "padding-bottom", "padding-left"] },
  ],
  layout: [
    { pair: [["width", "inspLblWidth"], ["height", "inspLblHeight"]] },
    { wide: "display" },
  ],
  type: [
    { wide: "font-family" },
    { pair: [["font-size", "inspLblSize"], ["line-height", "inspLblLeading"]] },
    { pair: [["font-weight", "inspLblWeight"], ["letter-spacing", "inspLblTracking"]] },
  ],
  color: [
    { wide: "color" },
    { wide: "background-color" },
    { wide: "border-color" },
    { pair: [["border-width", "inspLblBorder"], ["border-radius", "inspLblRadius"]] },
  ],
};

/** Смуга з чотирьох полів зі стрілками. Відсутнє в payload поле просто не
 *  малюється: стрілка називає бік сама, тож три поля з чотирьох лишаються
 *  правдою, а не зсувом. */
function quadHTML(block, take, opts) {
  const cells = block.quad.map((p) => take(p)).filter(Boolean);
  if (!cells.length) return "";
  return `<p class="insp-lbl">${esc(t(block.lbl))}</p>`
    + `<div class="insp-quad">${cells.map((d) => fieldHTML(d, opts(d))).join("")}</div>`;
}

/** Пара у дві колонки з підписами НАД полями. Підпис малюється лише для тієї
 *  половини, яка справді приїхала, — інакше колонка мала б назву без поля. */
function pairHTML(block, take, opts) {
  const cells = block.pair.map(([p, key]) => ({ d: take(p), key })).filter((c) => c.d);
  if (!cells.length) return "";
  return `<div class="insp-pairlbl">${cells.map((c) => `<span>${esc(t(c.key))}</span>`).join("")}</div>`
    + `<div class="insp-grid">${cells.map((c) => fieldHTML(c.d, opts(c.d))).join("")}</div>`;
}

/**
 * Секція звіту: заголовок і поля в розкладці `LAYOUT`.
 *
 * `take(prop)` віддає декларацію ОДИН раз і викреслює її зі списку: так
 * «решта» наприкінці — це рівно те, чого не назвала розкладка, і жодна
 * властивість не малюється двічі.
 */
function sectionHTML(key, items, tunedMap, tunable) {
  const left = new Map();
  for (const d of items) if (d && typeof d.prop === "string") left.set(d.prop, d);
  const take = (p) => {
    const d = left.get(p);
    if (d) left.delete(p);
    return d || null;
  };
  /* Прапорець гасить УСІ ручки поля одразу — і позначку «накручено» разом із
     ними: у документі без проводки вона означала б «тут щось змінено, і
     вернути це вам нічим». */
  const opts = (d) => ({
    tunable,
    wide: true,
    tuned: tunable && tunedMap
      && Object.prototype.hasOwnProperty.call(tunedMap, d.prop)
      ? tunedMap[d.prop] : null,
  });
  const inStrip = (d) => ({ ...opts(d), wide: false });

  /* Широкі рядки поспіль ідуть в ОДНУ сітку, а не кожен у свою: проміжок між
     полями дає `gap` сітки, і три сітки поспіль склеїли б три кольори в одну
     суцільну смугу без жодного зазору. */
  let body = "";
  let wide = [];
  const flush = () => {
    if (!wide.length) return;
    body += `<div class="insp-grid">${wide.map((d) => fieldHTML(d, opts(d))).join("")}</div>`;
    wide = [];
  };
  for (const block of LAYOUT[key] || []) {
    if (block.wide) {
      const d = take(block.wide);
      if (d) wide.push(d);
      continue;
    }
    flush();
    if (block.quad) body += quadHTML(block, take, inStrip);
    else if (block.pair) body += pairHTML(block, take, inStrip);
  }
  /* Решта — широкими рядками, у порядку payload. Сюди падає вся група `flex`
     і будь-яка нова властивість у `GROUPS`: рядок, що не поміщається в
     розкладку, мусить бути видимим, а не зниклим. */
  for (const d of left.values()) wide.push(d);
  flush();
  return `<section class="insp-spec"><h6>${esc(title(key))}</h6>${body}</section>`;
}

/**
 * `reportHTML(payload)` — payload на вході, рядок HTML на виході.
 *
 * `payload`:
 *   crumbs: string[] — короткі підписи елементів від кореня до самого
 *     елемента (`label()`, `inspector-dom.js`); остання крихта — сам елемент.
 *   groups: Object<string, Decl[]> — секції в порядку `GROUPS`
 *     (`inspector-dom.js`); ключі збігаються з `TITLE_KEY` вище.
 *   blocked, partial: boolean — застереження про неповний каскад (чужий
 *     origin / нерозібрані `@layer`/`@container`).
 *   tuned: Object<string, {from, to}> | null — що дизайнер НАКРУТИВ на цьому
 *     елементі (Task 14). Доліплює це поле БАТЬКО (`paintInsp`, `app.js`), а
 *     не оверлей: модель тюнера живе в батьківському вікні, бо рамка макета
 *     перезавантажується, а вона — ні, і оверлей про неї не знає нічого.
 *     Ключ — властивість; рендерер бере звідси `from` (у титул: від чого
 *     пішли) і сам факт «накручено» (`data-tuned`, синє тло поля). Без
 *     `tunable` поле ігнорується цілком.
 *     `missing: true` на правці — вона в пакеті Є, а на ЦЬОМУ документі її
 *     немає (селектор не знайшов елемента; `tuneMissing`, `app.js`). Тоді
 *     поле лишається накрученим (правка справжня), але каже про це:
 *     `data-miss` і окремий рядок у титулі. Інакше поле показувало б
 *     недоторкане число сторінки під синім тлом «накручено» — тобто рівно ту
 *     розбіжність, через яку тюнер і почав брехати.
 *
 * `null` (нічого не запінено) -> `""`, а не порожня рамка секцій: панель
 * оболонки (`app/shell-inspect.js`) саме за порожнім рядком вирішує, чи
 * показувати підказку «наведи на елемент» замість звіту.
 *
 * `opts.tunable` — чи МАЛЮВАТИ ручки тюнера (крутилку, пікер).
 *
 * ⛔ Це не косметика і не налаштування смаку, а те, чи документ узагалі здатен
 * ручку провести. Рендерер монтується у ДВА документи (шапка файла): у праву
 * панель оболонки і — для сторінки, відкритої БЕЗ канваса, — у shadow-корінь
 * самого оверлея (`_renderPanel`, `inspector.js`). Проводка ручок
 * (`data-act="insptune"` → `BAR_ACTIONS.insptune` → модель тюнера) живе в
 * БАТЬКІВСЬКОМУ вікні, і живе там свідомо: рамка макета перезавантажується, а
 * модель — ні. У документі оверлея її немає й не буде, тож ручки там не
 * «поки не підключені», а непідключувані.
 *
 * Типове значення — `false`, і саме в цей бік: забутий прапорець мусить дати
 * ЧЕСНИЙ ТЕКСТ, а не мертву ручку. До 18.09.2026 ручки малювались безумовно, і
 * на голій сторінці макета їх було 15 крутилок і 3 пікери — жодна ні на що не
 * реагувала. Це рівно та вада, від якої застерігає докстрінг `NUMERIC` вище,
 * лише застосована до значень, а не до документів.
 */
/**
 * Що сказати про саму ДИЗАЙН-СИСТЕМУ, під якою читається цей звіт.
 *
 * ⛔ НАПРЯМОК БЕЗ ДС МУСИТЬ СКАЗАТИ ПРО СЕБЕ ВГОЛОС. У `seo` дизайн-системи
 * немає свідомо — тема сайту живе поза нею, — і мовчазна відсутність звірки
 * виглядала б рівно як успішна звірка: ті самі зелені крапки, той самий
 * інтерфейс. Дизайнер вирішив би, що 589 змінних лендінга перевірені, хоча не
 * перевірена жодна. Отже — рядок про це, і не застереженням (`insp-warn`,
 * бурштин), бо нічого поганого не сталось: це факт про задачу, а не вада
 * макета.
 *
 * Коли ДС Є — теж рядок, і теж не декоративний: вирок «перевизначено»
 * спирається на конкретний коміт знімка, і дизайнер має право бачити, на
 * який саме, не питаючи нікого.
 *
 * ДС ПРОСТОРУ (профіль `space:<id>`, етап 2а) коміту не має — її токени
 * читаються з CSS-файла на льоту, — тож замість коміту рядок називає ФАЙЛ
 * (`info.source`). Сам профіль у текст не їде: `space:<id>` — внутрішній ключ
 * простору, не те, що дизайнер упізнає; файл — упізнає.
 */
function dsNote(info) {
  if (!info || typeof info !== "object") return "";
  let text;
  if (info.known && isSpaceProfile(info.profile)) {
    text = t("inspDsSpace", String(info.source || ""));
  } else if (info.known) {
    text = t("inspDsOn", String(info.profile || ""), String(info.commit || "").slice(0, 12));
  } else {
    text = t("inspDsNone", String(info.profile || ""));
  }
  return `<p class="insp-note">${esc(text)}</p>`;
}

export function reportHTML(payload, { tunable = false } = {}) {
  if (!payload) return "";
  const crumbs = payload.crumbs
    .map((name, i) => `<button data-act="inspcrumb" data-val="${i}">${esc(name)}</button>`)
    .join("");
  const warn = (on, key) => (on ? `<p class="insp-warn">${esc(t(key))}</p>` : "");
  const secs = Object.entries(payload.groups)
    .map(([k, items]) => sectionHTML(k, items, payload.tuned, tunable)).join("");
  return `<div class="insp-crumbs">${crumbs}</div>`
    + warn(payload.blocked, "inspBlocked") + warn(payload.partial, "inspPartial")
    + dsNote(payload.dsInfo) + secs;
}
